-- Migration 0108: Campfire Weeks 2 to 6 Phase 2 Content & RPC Upgrades (Gold Standard Sync)
-- Generated by scripts/gen-campfire-sql.ts from src/data/campfireDaysData.ts, src/data/fanOutLeads.ts,
-- src/data/fragmentMeaningQuestions.ts, src/data/weekQuestions.ts, and src/data/chapterScripts.ts.

-- The Campfire for Week 2, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 2, 1, '{"place":"The mine, then the mill road","narrated":false,"tone":"wry","cupNight":true,"opener":"Beds are in the barn tonight. Pick a corner and take it.","questionTitle":"The cart passed three sleeping farms in the dark and stopped only at the mill. Why?","forkA":"Someone was waiting on the road to guide them in.","forkB":"They had one destination before they ever entered the valley.","callback":"The mine wall put Tamsin''s name first and Corin''s second. Tamsin heard them say \"the mill boy next\".","nudge":"{friend:Aim}, an old man with two winters of firewood split behind him, watching one road. What was he waiting for?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How did the cart travel in the dark?","clickText":"The horse never checked at the fork on the way up, and coming down the wheels sank deep into the verge. The cart went up empty and came down laden."},"clicks":[{"a":"2-1-1","b":"2-1-3","text":"The horse never checked at the fork on the way up, and coming down the wheels sank deep into the verge. The cart went up empty and came down laden.","solves":true}],"riddle":null,"leads":[{"id":"2-1-1","place":"the bench by his door","actions":[{"attr":"Charm","verb":"let him tell it his own way"},{"attr":"Intellect","verb":"ask him about the horse, not the men"}],"clueTitle":"The steady horse","clueText":"The old man says the horse never balked at his gate or at the fork, in full dark and with no lamp. It took the mill lane at a steady walk.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-1-2","place":"the fresh ruts in the lane","actions":[{"attr":"Aim","verb":"follow the ruts past his gate"},{"attr":"Craft","verb":"read where the wheels ran"}],"clueTitle":"Past the gate","clueText":"The ruts run past his gate without a check or a pause, straight toward the mill. The cart did not turn its wheels for any other house in the lane.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-1-3","place":"where the cart turned upriver","actions":[{"attr":"Agility","verb":"run down to the turn before dark"},{"attr":"Aim","verb":"read the turn in the half-light"}],"clueTitle":"Deeper coming down","clueText":"Where the cart turned upriver, the ruts coming down sink deeper into the verge than the ruts going up.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"We held his last wall.\"* If it was meant to fall, why stand on it?","weekQuestion":"Why these children, and not any others?","pull":"**The mill is an hour on. At first light: what did the family see?**"}'::jsonb),
('dark-moon', 1, 2, 2, '{"place":"The mill","narrated":false,"tone":"wry","cupNight":false,"opener":"Asked for by name, and by the night he was born. That''s a strange thing to ask for.","questionTitle":"How did a stranger know the night the boy was born?","forkA":"From an old record kept somewhere far from here.","forkB":"Someone from this valley told him.","callback":"In the mine, that shape was a hole, and what sat in it was gone. Here it''s cut into the mill''s footing.","nudge":"{friend:Craft}, look at that footing stone again. The wheel is fifty years old, but the mark under it is older than the valley. How long has that mark been waiting?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Did he hesitate once he reached the house?","clickText":"The mud on the floorboards runs in one unbroken line from the door to the child''s bed, and the paper was in his fist before he crossed the threshold. He did not search the house."},"clicks":[{"a":"2-2-1","b":"2-2-2","text":"The mud on the floorboards runs in one unbroken line from the door to the child''s bed, and the paper was in his fist before he crossed the threshold. He did not search the house.","solves":true}],"riddle":null,"leads":[{"id":"2-2-1","place":"the doorway, with her","actions":[{"attr":"Charm","verb":"ask her what was in his hands"},{"attr":"Intellect","verb":"ask her what he did before he spoke"}],"clueTitle":"The paper in his fist","clueText":"She says he had a folded paper in his fist. He looked at it once, then said the boy''s name.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-2-2","place":"inside the mill door","actions":[{"attr":"Aim","verb":"follow his boot-marks inside"},{"attr":"Craft","verb":"read the dried mud on the boards"}],"clueTitle":"Straight to the bed","clueText":"Nobody has swept since. His dried boot-mud goes from the door straight to the boy''s bed and back, and never turns aside.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-2-3","place":"the yard where the cart stood","actions":[{"attr":"Aim","verb":"walk the yard by the light from the door"},{"attr":"Craft","verb":"read what the horse left behind"}],"clueTitle":"The cropped grass","clueText":"Where the cart stood in the yard, the grass is cropped short in a wide half-circle, as far as a tethered horse can reach.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"By the third, we had stopped.\"* Did they stop counting because they lost hope, or because the numbers stopped mattering?","weekQuestion":"Why these children, and not any others?","pull":"**Upriver. The ruts are four nights old, and there is weather coming.**"}'::jsonb),
('dark-moon', 1, 2, 3, '{"place":"Upriver","narrated":false,"tone":"wry","cupNight":false,"opener":"A stranger dead at a lock, and the lock opens for you. Stone doesn''t have favorites without a reason.","questionTitle":"The dead man picked at the housing for days. Why did it give under your bare hand?","forkA":"The stone woke to the fragments in our pack.","forkB":"The stone woke to the hand that touched it.","callback":"Corin was asked for by name. Today a lock that wouldn''t open for a dead man opened for you.","nudge":"{friend:Intellect}, a dog chained between two rocks four nights ago, fed fresh meat, and a dead man left on the path. Who is keeping that road?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Why didn''t anyone rob him?","clickText":"He worked that stone for days with steel, and his belt is still weighted with coin. The path-keeper stepped over his body for a week and took neither his tools nor his purse."},"clicks":[{"a":"2-3-1","b":"2-3-2","text":"He worked that stone for days with steel, and his belt is still weighted with coin. The path-keeper stepped over his body for a week and took neither his tools nor his purse.","solves":true}],"riddle":null,"leads":[{"id":"2-3-1","place":"the stone round the housing","actions":[{"attr":"Craft","verb":"look at the stone round the lock"},{"attr":"Intellect","verb":"read the marks cut into it"}],"clueTitle":"The scratches","clueText":"The stone round the housing is scored with dozens of short scratches, some weathered and some bright. He tried it more than once, on more than one day.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"2-3-2","place":"the stranger on the path","actions":[{"attr":"Charm","verb":"kneel by him and close his eyes"},{"attr":"Intellect","verb":"go through what he carried"}],"clueTitle":"Silver in his purse","clueText":"His purse is still on his belt, and there is silver in it. A week of people have stepped over him, and not one has taken it.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"2-3-3","place":"the narrows where the dog lies","actions":[{"attr":"Might","verb":"hold the chain short and get past"},{"attr":"Aim","verb":"look past the dog from the rocks"}],"clueTitle":"The full pail","clueText":"Behind the dog, at the end of its chain, stands a pail of water, full and clean. There is a scrap of fresh meat beside it.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Ours was the last light burning.\"* When every other light has gone out, why keep yours lit?","weekQuestion":"Why these children, and not any others?","pull":"**Where was he trying to get to? The path goes on past him, and up.**"}'::jsonb),
('dark-moon', 1, 2, 4, '{"place":"The shaft in the hillside","narrated":false,"tone":"quiet","cupNight":false,"opener":"Sit down. Keep your voices under the wind.","questionTitle":"They pulled the ladder, but they didn''t run. Why didn''t they scatter when we were spotted?","forkA":"They have too many guards down there to fear four people.","forkB":"Whatever they are doing to the boy cannot be paused for anything.","callback":"Yesterday a branch swung on the slope with no wind. Today they knew you were at the shaft.","nudge":"{friend:Charm}, you saw his hands before they hauled the ladder up. Not a scratch on him yet. What are they waiting for?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"2-4-1","place":"the foot of the shaft","actions":[{"attr":"Aim","verb":"look down past the edge"},{"attr":"Agility","verb":"creep back to the lip and look"}],"clueTitle":"The second lamp","clueText":"A second lamp stands lit at the foot of the shaft, filled and trimmed, the same make as the ring in the chamber. Nobody grabbed it in a hurry.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"2-4-2","place":"the timbers at the shaft''s mouth","actions":[{"attr":"Craft","verb":"look over the timbering at the top"},{"attr":"Aim","verb":"follow the timber down by the lamplight"}],"clueTitle":"The pale scar","clueText":"On the timbering just below the top, a fresh pale scar runs down the wood, where a stone knocked loose went bouncing all the way to the bottom.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"2-4-3","place":"the voices down the shaft","actions":[{"attr":"Aim","verb":"lie flat at the edge and listen"},{"attr":"Intellect","verb":"count the voices as they go round"}],"clueTitle":"The chant ran on","clueText":"When the shout went up, the heads turned, but the chant never stopped. It ran on under the shout the whole time, the same few words.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"His hand was bleeding, and he told us to sleep.\"* What price did he pay down there so they could sleep?","weekQuestion":"Why these children, and not any others?","pull":"**Is there another way into this hill, before they finish? You have tonight to find it.**"}'::jsonb),
('dark-moon', 1, 2, 5, '{"place":"The hillside by night","narrated":false,"tone":"wry","cupNight":false,"opener":"A circle of black cloth, and a man who fought without a word. Somebody wanted a name forgotten.","questionTitle":"Meira found every record of him scraped clean. Who erased his name from the world?","forkA":"His enemies tore his name down to break those who followed him.","forkB":"His own people hid his name to keep what he did a secret.","callback":"On Day 2 a horn button, on Day 3 a dead stranger. Tonight, a circle.","nudge":"{friend:Intellect}, a scout who fights without a sound, tears his own coat to get free, and flashes a lamp twice toward the dark. Who teaches a man to fight like that?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Were the stones broken or hidden?","clickText":"The carved monuments on the ridge were shattered with fire and mallet, but the cut stones in the sheepfold were laid face-inward against each other. Some were broken in anger, and some were hidden with care."},"clicks":[{"a":"2-5-2","b":"2-5-3","text":"The carved monuments on the ridge were shattered with fire and mallet, but the cut stones in the sheepfold were laid face-inward against each other. Some were broken in anger, and some were hidden with care.","solves":true}],"riddle":null,"leads":[{"id":"2-5-1","place":"the old stone where he signalled","actions":[{"attr":"Craft","verb":"run a hand over each face of it"},{"attr":"Aim","verb":"look at it side-on by the lamp"}],"clueTitle":"The ground-flat face","clueText":"On the old stone where the scout stood, one face has been ground flat, long ago. The chisel scars are weathered grey. Whatever was carved there is gone.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-5-2","place":"the scree below the stone","actions":[{"attr":"Agility","verb":"scramble down the scree"},{"attr":"Aim","verb":"search the scree by lamplight"}],"clueTitle":"Burned chips","clueText":"Mixed into the scree are chips of dressed stone, blackened by fire. One still carries the curve of a carved letter, broken off mid-word.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-5-3","place":"the fallen sheepfold","actions":[{"attr":"Might","verb":"lift the fallen stones one by one"},{"attr":"Craft","verb":"look at how the fold was built"}],"clueTitle":"Faces turned in","clueText":"The fold''s old cut stones were laid with their carved sides turned inward, against each other, every one. From outside, the wall shows nothing.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Not one of us who would not have died for him.\"* What kind of leader earns that kind of silence?","weekQuestion":"Why these children, and not any others?","pull":"**There is no second door on this hillside, and now there is a clock. Last week, six cold slivers showed you a way nobody was watching. You have five.**"}'::jsonb),
('dark-moon', 1, 2, 6, '{"place":"The lip of the shaft","narrated":false,"tone":"wry","cupNight":true,"opener":"Picks in the deep rock. They''re digging toward something that was here before them.","questionTitle":"The fragments drew a map to an older room. Why are they digging toward that same room tonight?","forkA":"They know what is inside that room, and came to take it.","forkB":"They are digging toward the boy, and do not know the old room exists.","callback":"In the mine, you reached the mark after it was emptied. Tonight they''re still digging toward the older room.","nudge":"{friend:Might}, feel that vibration through the turf. Those picks haven''t rested once since twilight. How many men are down there swinging iron?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"What are the picks searching for?","clickText":"The pick-strokes fall in one unbroken line toward the deeper stone, and every basket of earth is sifted through bare fingers. They are not clearing rock for a tunnel. They are searching for something small."},"clicks":[{"a":"2-6-1","b":"2-6-2","text":"The pick-strokes fall in one unbroken line toward the deeper stone, and every basket of earth is sifted through bare fingers. They are not clearing rock for a tunnel. They are searching for something small.","solves":true}],"riddle":null,"leads":[{"id":"2-6-1","place":"the ground over the picks","actions":[{"attr":"Craft","verb":"feel the strokes through the turf"},{"attr":"Intellect","verb":"time the strokes and place them"}],"clueTitle":"One line","clueText":"The strokes come from one place only, and each new stroke lands a little nearer the old shaft than the last.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-6-2","place":"the two lamps at the foot","actions":[{"attr":"Aim","verb":"watch what passes the lamps"},{"attr":"Agility","verb":"crawl to the edge and look down"}],"clueTitle":"Sifted by hand","clueText":"In the lamplight at the foot of the shaft, baskets of dug earth are tipped out. Someone kneels and sifts each one through their hands before it is thrown aside.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-6-3","place":"the hole under the old stone","actions":[{"attr":"Might","verb":"shift one more stone"},{"attr":"Agility","verb":"squeeze in to the first step"}],"clueTitle":"Your own print","clueText":"Under the stones, the first step down is thick with dust. In the dust there is no print but your own.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"Morning came. The enemy did not.\"* Where does an enemy go when they vanish without a sound?","weekQuestion":"Why these children, and not any others?","pull":"**They are digging toward the old room. Be in it first.**"}'::jsonb)
on conflict (series_id, season_number, week, day) do update set data = excluded.data;

-- The Campfire for Week 3, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 3, 1, '{"place":"Somewhere warm","narrated":false,"tone":"wry","cupNight":false,"opener":"Somewhere warm. I''d settle for a warm supper. Eat.","questionTitle":"Corin said they promised Wren she was going home first. Why tell a stolen child that?","forkA":"A lie to keep a child quiet and docile on the road.","forkB":"The truth: her home in the burned country is where their work needed her.","callback":"Corin was held a morning''s walk from his own mill. Wren was told she was going home first.","nudge":"{friend:Intellect}, a child''s mitten tucked in Corin''s belt, smelling of sheep. Who gives a mitten to another child in the dark?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Did the cart make ready for a long journey?","clickText":"The cart below the shaft took the west road without checking, and on the ridge above the runner paused only to watch that same line. They did not search for a trail. They set their faces toward the burned hills and walked."},"clicks":[{"a":"3-1-2","b":"3-1-3","text":"The cart below the shaft took the west road without checking, and on the ridge above the runner paused only to watch that same line. They did not search for a trail. They set their faces toward the burned hills and walked.","solves":true}],"riddle":null,"leads":[{"id":"3-1-1","place":"Corin, on the walk down","actions":[{"attr":"Charm","verb":"walk beside him and let him talk"},{"attr":"Aim","verb":"look him over in the morning light"}],"clueTitle":"The grey wool","clueText":"Corin has a child''s woollen mitten tucked in his belt that is not his. The wool is rough and grey, and it smells of sheep.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-1-2","place":"where the cart stood, below the shaft","actions":[{"attr":"Craft","verb":"read what the cart left in the grass"},{"attr":"Intellect","verb":"work out what they loaded"}],"clueTitle":"The fresh turn","clueText":"Where the cart stood below the shaft, the ruts cut clean into the turf, turning west onto the old road without a moment''s pause.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-1-3","place":"the shoulder of the hill he ran over","actions":[{"attr":"Agility","verb":"go up the shoulder after him"},{"attr":"Aim","verb":"follow his line from the shaft mouth"}],"clueTitle":"Facing west","clueText":"At the top of the shoulder the ground is scuffed where he stood a while, facing west. Then his prints go on, the same way the cart went.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Then they stopped being ours.\"* Whose were they, and what took them?","weekQuestion":"What do they need Wren for?","pull":"They are not hiding her. They told her she was going home.\n\n**Why would anyone take a stolen child back to where she was born? Ashcombe: a long day west.**"}'::jsonb),
('dark-moon', 1, 3, 2, '{"place":"Ashcombe","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"The men in grey coats spoke politely and promised she''d only be needed once. Was that courtesy genuine?","forkA":"Yes: they take what the rite requires, and let the children go.","forkB":"No: a polite kidnapper is only a kidnapper who hates a scene.","callback":"Tamsin and Corin each came home with one cut palm, bound clean. Wren''s taker said they''d only need her the once.","nudge":"{friend:Charm}, chips of black glass set in a row on her windowsill, dusted around with care. Why leave them behind?","nudgeIfLaid":null,"narratedSilence":"Garrick sits by the hearth with his boots off, watching the embers in silence.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"3-2-1","place":"the well, and the board of chips","actions":[{"attr":"Charm","verb":"crouch by the board and wait"},{"attr":"Aim","verb":"watch the well from across the street"}],"clueTitle":"The boy at the well","clueText":"At the well a boy holds his chip out low and quick, then shoves it back into his shirt before you have looked at it properly.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-2-2","place":"the empty cart at the foot of the black road","actions":[{"attr":"Craft","verb":"climb up and look over the boards"},{"attr":"Intellect","verb":"go over the cart end to end"}],"clueTitle":"The made bed","clueText":"In the bed of the empty cart a sheepskin is spread over the boards, and a blanket is folded at one end like a pillow.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-2-3","place":"the street, where every door shut","actions":[{"attr":"Aim","verb":"walk the street with your eyes on the ground"},{"attr":"Craft","verb":"pick out what is caught between the stones"}],"clueTitle":"Sacking on the stones","clueText":"Caught between the stones down the middle of the street are scraps of sacking. It is the kind men tie over hooves to quiet them on a night road.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Remember that, when you hear where else we stood.\"* Where else might they have stood?","weekQuestion":"What do they need Wren for?","pull":"**What does anyone need a child for, once? The Blackglass: half a day up the black road, the place Meira marked.**"}'::jsonb),
('dark-moon', 1, 3, 3, '{"place":"The Blackglass","narrated":false,"tone":"wry","cupNight":false,"opener":"Mind your hands on that glass, all of you.","questionTitle":"Three children live beside three Seeker marks. Why did the riders carry Wren straight past the Blackglass?","forkA":"They cannot open these ancient housings; they need an older entrance.","forkB":"The marks are not their goal; they are only the guide-stones to the Kiln.","callback":"At the Widow''s Tooth a man lay in the bracken watching the rock. Here the riders went past this one without slowing.","nudge":"{friend:Intellect}, Meira''s note in the margin: ''Five, the fragment says. Every other record says four.'' Why would a scholar write down a number she doubted?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Has anyone touched this housing since the road was made?","clickText":"The old shepherds'' path ends dead at the sunken stones, and the fine dust over the housing was undisturbed until your fingers reached it. The riders stayed on the crest and rode past without once looking down."},"clicks":[{"a":"3-3-1","b":"3-3-2","text":"The old shepherds'' path ends dead at the sunken stones, and the fine dust over the housing was undisturbed until your fingers reached it. The riders stayed on the crest and rode past without once looking down.","solves":true}],"riddle":null,"leads":[{"id":"3-3-1","place":"where the shepherds'' path meets the glass","actions":[{"attr":"Intellect","verb":"look at where the path gives out"},{"attr":"Agility","verb":"walk the edge of the glass"}],"clueTitle":"The row of stones","clueText":"Where the shepherds'' path meets the glass, a row of old stones lies across it, sunk deep in the turf. The path stops dead at the row.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"3-3-2","place":"the housing beside the mark","actions":[{"attr":"Craft","verb":"run a finger round its carving"},{"attr":"Intellect","verb":"look it over before you step away"}],"clueTitle":"Only your hand","clueText":"The glass round the housing is dull with fine dust. The only marks in it are the ones your own hand just made.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"3-3-3","place":"the far edge, where the glass is cracked","actions":[{"attr":"Aim","verb":"look back the way you came"},{"attr":"Might","verb":"climb onto the highest lip of glass"}],"clueTitle":"The view down","clueText":"From the far edge you can see all the way down the black road to Ashcombe''s roofs, and the well in the middle of them.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"He only never told us the price.\"* The price of what?","weekQuestion":"What do they need Wren for?","pull":"**They rode straight past the one thing Meira marked. So what are they riding to? On, into the black ridges.**"}'::jsonb),
('dark-moon', 1, 3, 4, '{"place":"The black ridges","narrated":false,"tone":"wry","cupNight":true,"opener":"Whoever slept in these niches had long nights too. Build the fire in the doorway.","questionTitle":"Wren is dropping glass chips from the saddle of six horses. Have the riders truly not noticed?","forkA":"They believe a small child is helpless and don''t watch her hands.","forkB":"They see the chips, but know the trail ends where no one can follow.","callback":"Tamsin wasn''t asleep; she was counting. Wren is dropping her chips, one by one, on their trail.","nudge":"{friend:Craft}, a bone die with its spots worn smooth, left in a sleeping niche centuries ago. What kind of soldiers played with that?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Did she drop the chips in haste or with care?","clickText":"Each chip was set on high bare rock where the starlight catches it, and the backs are scored with tiny knife-scratches: one, two, three. She is laying a numbered line across the dark."},"clicks":[{"a":"3-4-1","b":"3-4-3","text":"Each chip was set on high bare rock where the starlight catches it, and the backs are scored with tiny knife-scratches: one, two, three. She is laying a numbered line across the dark.","solves":true}],"riddle":null,"leads":[{"id":"3-4-1","place":"the rises along the riders'' trail","actions":[{"attr":"Aim","verb":"look back down the trail from the last rise"},{"attr":"Agility","verb":"run the trail back to the first chip"}],"clueTitle":"On the bare rock","clueText":"Each chip lay on bare rock at the top of a rise, never down in the ash where it would sink. Coming up behind, you see each one glint before you reach it.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"3-4-2","place":"the bone-white trees along the trail","actions":[{"attr":"Intellect","verb":"set each chip beside what stood near it"},{"attr":"Aim","verb":"look round from where each one lay"}],"clueTitle":"A tree at each","clueText":"Each chip lay a few paces from a dead tree, the tallest one in sight. Stand at one tree, and you can see the next.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"3-4-3","place":"the three chips in your hand","actions":[{"attr":"Craft","verb":"turn each one over in the light"},{"attr":"Intellect","verb":"lay them out side by side"}],"clueTitle":"Scratched on the back","clueText":"Turn the chips over. One has a single short scratch on its back, one has two, and one has three.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We locked with what we are.\"* What are they?","weekQuestion":"What do they need Wren for?","pull":"**She is alive, and she is thinking. The hut, at first light.**"}'::jsonb),
('dark-moon', 1, 3, 5, '{"place":"The shepherd''s hut","narrated":false,"tone":"wry","cupNight":false,"opener":"For the first time all season, they ran. Sit down and breathe.","questionTitle":"They gave Wren the warm bed by the hearth, yet fled in the night leaving their pot on the fire. What made them run?","forkA":"Fear: our fire on the ridge showed them they were being hunted.","forkB":"The hour: the time for waiting expired, and the Kiln must be lit.","callback":"At the mine someone took the time to bind Tamsin''s hand in clean linen. Here someone folded one blanket with care, and threw the other down.","nudge":"{friend:Might}, cut deep into the beam over her bed: ''Until the throne rise whole.'' Who carves a prayer over a stolen child''s pillow?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How quickly did they depart?","clickText":"By the spring a full water skin lies abandoned where it was dropped, while inside the hut Wren''s keepsakes were left undisturbed in their row on the sill. The hurry was sudden, but it began outside the room."},"clicks":[{"a":"3-5-2","b":"3-5-3","text":"By the spring a full water skin lies abandoned where it was dropped, while inside the hut Wren''s keepsakes were left undisturbed in their row on the sill. The hurry was sudden, but it began outside the room.","solves":true}],"riddle":null,"leads":[{"id":"3-5-1","place":"low on the doorframe","actions":[{"attr":"Craft","verb":"run a thumbnail along the letters"},{"attr":"Intellect","verb":"look at how each letter was made"}],"clueTitle":"Cut twice","clueText":"Each stroke of the name has been cut twice, the second pass deeper than the first.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-5-2","place":"the spring below the hut","actions":[{"attr":"Agility","verb":"get down to the water fast"},{"attr":"Aim","verb":"look over the ground by the spring"}],"clueTitle":"The dropped skin","clueText":"By the spring a water skin lies in the grass, half full. Its stopper is a pace away.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-5-3","place":"the wall beside the pallet","actions":[{"attr":"Charm","verb":"sit on the pallet and look round"},{"attr":"Intellect","verb":"look at what is kept by the bed"}],"clueTitle":"The gap in the row","clueText":"Along the wall by the pallet, small things are set out in a row: a twist of grey wool, a white pebble, a hen''s feather. At one end there is a gap, and the dust there is clean.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"That is why kingdoms fear them.\"* Why would a kingdom fear a family?","weekQuestion":"What do they need Wren for?","pull":"**A step, now, and no more. If they could see you, can you see them? The cairn on the highest ridge, before the light goes.**"}'::jsonb),
('dark-moon', 1, 3, 6, '{"place":"The cairn","narrated":false,"tone":"wry","cupNight":false,"opener":"Fire''s built up. Sit by it before you decide anything.","questionTitle":"An hour after we read the map into the wind, a single lamp climbed the Kiln and went inside. Who carried it?","forkA":"A watcher who heard our voices and went in to warn the others.","forkB":"The last of the faithful arriving for the ritual, unaware of us.","callback":"Corin said Wren''s home was always warm. Tonight the map ends at a hill that breathes warm air.","nudge":"{friend:Agility}, the knife-edge drops straight to scree on both sides. If we go down in the dark, how do we keep from sliding?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Are the riders still inside the hill?","clickText":"No horses wait outside in the dark, and from the crown''s crack thin pale smoke has begun to rise into the cold air. The lamp has reached the deep chamber, and the hearth is burning."},"clicks":[{"a":"3-6-1","b":"3-6-2","text":"No horses wait outside in the dark, and from the crown''s crack thin pale smoke has begun to rise into the cold air. The lamp has reached the deep chamber, and the hearth is burning.","solves":true}],"riddle":null,"leads":[{"id":"3-6-1","place":"the foot of the round hill","actions":[{"attr":"Aim","verb":"look down at the foot of the hill"},{"attr":"Intellect","verb":"go over every shape below the crown"}],"clueTitle":"No horses","clueText":"Not one horse is tethered at the foot of the Kiln.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-6-2","place":"the crack across its crown","actions":[{"attr":"Aim","verb":"watch the crown after the lamp goes in"},{"attr":"Intellect","verb":"watch the air over the crack"}],"clueTitle":"Smoke from the crack","clueText":"Soon after the lamp goes in, thin pale smoke starts to rise from the crack. By daylight there was only shimmering air.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-6-3","place":"the knife-edge below the cairn","actions":[{"attr":"Agility","verb":"go a little way back along the edge"},{"attr":"Might","verb":"test the stones of the face"}],"clueTitle":"No way down in the dark","clueText":"Now the light has gone, the knife-edge below the cairn is a black line with nothing either side. The face beside it drops straight to loose scree.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"We never dug him a grave.\"* Why not?","weekQuestion":"What do they need Wren for?","pull":"**Whatever happens under that hill has started. Into the Kiln, tonight.**"}'::jsonb)
on conflict (series_id, season_number, week, day) do update set data = excluded.data;

-- The Campfire for Week 4, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 4, 1, '{"place":"Under the Kiln, then Ashcombe","narrated":false,"tone":"wry","cupNight":false,"opener":"Count yourselves. I will, too.","questionTitle":"Someone stood among us in the dark with a bare blade, yet cut only rope. Why spare us?","forkA":"A lone rescuer couldn''t risk a fight in the dark without losing the prisoner.","forkB":"They had us at their mercy and were under orders not to harm us.","callback":"Every one of them you''ve fought has run at the first gap. Tonight one stood among you with a blade and cut only rope.","nudge":"{friend:Craft}, cut rope ends all clean on the same side, a finger''s width from the knot. Someone stepped out of that passage with a steady blade.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How did the prisoner get free in the dark?","clickText":"A lamp was just snuffed inside the side passage, and every rope was severed cleanly on the same side a finger''s width from the knot. A second person stepped out of the passage in the dark and cut him loose."},"clicks":[{"a":"4-1-1","b":"4-1-3","text":"A lamp was just snuffed inside the side passage, and every rope was severed cleanly on the same side a finger''s width from the knot. A second person stepped out of the passage in the dark and cut him loose.","solves":true}],"riddle":null,"leads":[{"id":"4-1-1","place":"the passage none of you had noticed","actions":[{"attr":"Agility","verb":"go a few steps in, without a lamp"},{"attr":"Intellect","verb":"stand in its mouth and take stock"}],"clueTitle":"The snuffed wick","clueText":"A few steps into the passage the air smells of a wick just put out. None of your lamps has been in there.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-1-2","place":"the place where he knelt","actions":[{"attr":"Aim","verb":"pace it out from the passage"},{"attr":"Intellect","verb":"work out what he could reach from there"}],"clueTitle":"Three paces","clueText":"Where he knelt is three paces from the passage mouth, in the corner your lamps lit least.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-1-3","place":"the ropes on the stone","actions":[{"attr":"Craft","verb":"lay the cut ends side by side"},{"attr":"Might","verb":"pick them up and test each one"}],"clueTitle":"The same side","clueText":"Every rope is cut a finger''s width from its knot, and every cut is on the same side.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"We did not trust four locks to hold what needed five.\"* If the four marks were not enough, what is the fifth lock?","weekQuestion":"Why has the Order left us alive?","pull":"*Already with us.* Joss is not waiting to be taken.\n\n**A blade within arm''s reach, in the dark, and it cut rope. Why are you still alive? The north road, at first light.**"}'::jsonb),
('dark-moon', 1, 4, 2, '{"place":"The north road","narrated":false,"tone":"wry","cupNight":true,"opener":"Cold road. Put your hands round that cup.","questionTitle":"Four armed riders guarded one small box from the Kiln, riding away from the lake. Why guard that box harder than the boy?","forkA":"The box holds what they actually came for; the child only wakes it.","forkB":"The cart was an open-road decoy meant to draw our eyes off the lake.","callback":"The carter''s coin has the king''s face scraped off. Meira wrote that every record of him had been scraped clean.","nudge":"{friend:Intellect}, bare swords across their saddles and eyes never leaving a single small box in the cart-bed. Why ride like that in broad daylight?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How did the four riders guard the cart through the settlements?","clickText":"They rode with bare blades across their saddles in broad daylight, never speaking and never once looking at the road or the lake. Every eye stayed locked on the single small box in the cart-bed."},"clicks":[{"a":"4-2-1","b":"4-2-2","text":"They rode with bare blades across their saddles in broad daylight, never speaking and never once looking at the road or the lake. Every eye stayed locked on the single small box in the cart-bed.","solves":true}],"riddle":null,"leads":[{"id":"4-2-1","place":"the carter, watering his horses","actions":[{"attr":"Charm","verb":"let him run on about the riders"},{"attr":"Intellect","verb":"ask how the four rode"}],"clueTitle":"Every eye on the cart","clueText":"The carter says the four never spoke to each other, and never once looked at the road or the lake. Every eye stayed on the cart.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-2-2","place":"the men in the shallows","actions":[{"attr":"Charm","verb":"sit down in the water with them"},{"attr":"Intellect","verb":"ask what made them let it pass"}],"clueTitle":"Blades bare","clueText":"They say the four came through the ford with their blades bare across their saddles, in full daylight, and did not slow down.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-2-3","place":"the ruts going north","actions":[{"attr":"Aim","verb":"follow them as far as the light lets you"},{"attr":"Craft","verb":"read where they could have turned off"}],"clueTitle":"The open road","clueText":"Their ruts keep to the open road the whole way, past every shepherd''s hut. A sheep-path along the ridge would have hidden them from all of it.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We feared it more than the other four together.\"* Why would the Seekers fear one of their own locks?","weekQuestion":"Why has the Order left us alive?","pull":"**Four armed men for one small box, riding away from the boy. What is in it? Reedham, by noon tomorrow.**"}'::jsonb),
('dark-moon', 1, 4, 3, '{"place":"Reedham","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"They took Joss eight nights ago — before we even reached the Kiln — and have kept him on the water ever since. What are they waiting for?","forkA":"A night or a water-level that hasn''t come yet to reach the drowned chamber.","forkB":"Someone else who had not reached Reedham yet: they have been waiting for us.","callback":"In Ashcombe a baby born when the moon goes out is given a chip of black glass. In Reedham every window is lit for one.","nudge":"{friend:Craft}, eight notches cut in her doorpost wood, and a boat heavier than her skiff touching the shingle by night.","nudgeIfLaid":null,"narratedSilence":"Garrick sits by the window looking out over the water, his arms folded in the quiet room.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"4-3-1","place":"the fisherman on the shingle","actions":[{"attr":"Charm","verb":"help him with his nets and listen"},{"attr":"Intellect","verb":"ask what he hears at night"}],"clueTitle":"The oars at dusk","clueText":"On the shingle the fisherman says he hears oars out on the lake every night, at the same hour, just after dusk. He has never gone to look.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"4-3-2","place":"the fresh keel-marks on the shingle","actions":[{"attr":"Craft","verb":"measure the groove against her skiff''s keel"},{"attr":"Intellect","verb":"read how deep the bow bit into the wet stones"}],"clueTitle":"Heavier than her skiff","clueText":"The fresh keel-marks beside her skiff are wider and cut twice as deep into the shingle. Whatever boat touched shore here was carrying four or five people, not one.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"4-3-3","place":"the tower''s lowest window","actions":[{"attr":"Agility","verb":"climb up to the sill from the skiff"},{"attr":"Aim","verb":"look it over from the water"}],"clueTitle":"A cleared sill","clueText":"On the tower''s lowest sill, on the side facing the shore road, the weed is scraped away in a patch the size of a seat. Someone has sat here in the dark looking back toward Reedham.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"So does anyone born in its dark.\"* What does a child born in the dark have in common with what fell?","weekQuestion":"Why has the Order left us alive?","pull":"Back on the shingle, beside the place her skiff was lying, there are keel-marks that are not hers. Fresh ones, pressed deep into the wet stones, and the lapping of the lake has not yet smoothed them.\n\nUp the lane, the lamp burns on in her window, small and steady in the afternoon.\n\n**Someone has been rowing out to the drowned village by night. Old Reedham, at the shallow end, tomorrow.**"}'::jsonb),
('dark-moon', 1, 4, 4, '{"place":"Old Reedham","narrated":false,"tone":"wry","cupNight":false,"opener":"Drowned roofs under the keel, and a page of Meira''s notes that survived the ash. Let''s hear what you found.","questionTitle":"Meira''s note says ''moon-blood'' is the old word for the marked, and the fragment warns against letting it near. What is the fragment warning against?","forkA":"Letting a marked child''s blood touch the Stones — the Order is doing what the Seekers feared.","forkB":"Letting a specific bloodline from the old songs near — ''moon-blood'' may mean more than the birth-mark.","callback":"At the ford, Tamsin''s small prints stopped at the water. Today Joss''s stop at the edge of deep water.","nudge":"{friend:Intellect}, she copied ''the marked'' on one page and ''moon-blood'' on another, then crossed out her second line in the margin until the nib tore through.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Was Meira sure of her own note on ''moon-blood''?","clickText":"Meira copied ''the marked'' and ''moon-blood'' from two separate old records, and under her gloss she began a second thought before scratching it out through the paper. She had a second thought she never finished."},"clicks":[{"a":"4-4-2","b":"4-4-3","text":"Meira copied ''the marked'' and ''moon-blood'' from two separate old records, and under her gloss she began a second thought before scratching it out through the paper. She had a second thought she never finished.","solves":true}],"riddle":null,"leads":[{"id":"4-4-1","place":"the drowned windows","actions":[{"attr":"Aim","verb":"look along the windows in the low light"},{"attr":"Craft","verb":"look at the iron in each frame"}],"clueTitle":"The old hooks","clueText":"In every drowned window frame is the same iron lamp-hook that hangs in Reedham''s windows today. Each one is black with old soot.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"4-4-2","place":"the earlier pages of her notes","actions":[{"attr":"Intellect","verb":"go back through them, page by page"},{"attr":"Craft","verb":"set the copied hands side by side"}],"clueTitle":"Two records","clueText":"Two pages back, she copied \"the marked\" out of a different record. The two words never appear in the same copied line.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"4-4-3","place":"the margin of her page","actions":[{"attr":"Intellect","verb":"read her note against the line"},{"attr":"Aim","verb":"hold the page to the lamp"}],"clueTitle":"The scratched line","clueText":"Under her note she began a second line, then scratched it out so hard the nib went through the paper.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"If it is ever let near.\"* Let near to what?","weekQuestion":"Why has the Order left us alive?","pull":"**A warning against what? The reed island, a mile out: the only place on this lake a boat can put in unseen.**"}'::jsonb),
('dark-moon', 1, 4, 5, '{"place":"The reed island","narrated":false,"tone":"wry","cupNight":false,"opener":"Pale curls of whittled wood. Somebody''s still carving.","questionTitle":"They ferry Joss between the island and the drowned streets by night, yet tonight a lamp is crossing to the empty tower. Why the tower tonight?","forkA":"They shift their watch-post across the lake so no one on shore can fix where the boy is held.","forkB":"They know we took their boat on the island today and are setting a watch for us at the tower.","callback":"At the Widow''s Tooth a little carved horse was left behind. Today, in their boat, a little carved hull was thrown away.","nudge":"{friend:Aim}, three willow cuts—one grey, one brown, one white—and tonight a single lamp moving out toward the tower.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How has Joss been kept on the reed island?","clickText":"The willow has had fresh shoots cut three days running, and the long shavings in the boat''s bilge were carved without haste. They have kept him dry and unharmed on the island by day while moving him across the lake by night."},"clicks":[{"a":"4-5-1","b":"4-5-3","text":"The willow has had fresh shoots cut three days running, and the long shavings in the boat''s bilge were carved without haste. They have kept him dry and unharmed on the island by day while moving him across the lake by night.","solves":true}],"riddle":null,"leads":[{"id":"4-5-1","place":"the rope in the bottom of their boat","actions":[{"attr":"Craft","verb":"sift the shavings out of the rope"},{"attr":"Intellect","verb":"look at how each one was cut"}],"clueTitle":"Long curls","clueText":"Every curl in the bottom of the boat is long and unbroken, and all of them are fresh. Nobody hurried him.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-5-2","place":"the stern seat","actions":[{"attr":"Craft","verb":"feel under the thwart"},{"attr":"Might","verb":"lift the seat board out"}],"clueTitle":"Folded dry","clueText":"Under the stern seat, out of the spray, a blanket is folded small. It is dry.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-5-3","place":"the willows at the water''s edge","actions":[{"attr":"Agility","verb":"work along the bank through the willows"},{"attr":"Craft","verb":"look at where the wood was cut"}],"clueTitle":"Three shoots","clueText":"One willow has had three straight shoots cut from it with a sharp blade. One cut is grey, one is brown, and one is still white.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Pray no one ever learns it is also a door.\"* Why build a lock that can still be opened like a door?","weekQuestion":"Why has the Order left us alive?","pull":"**Why would anyone keep watch on an empty tower? After that lamp, tonight, in their own boat.**"}'::jsonb),
('dark-moon', 1, 4, 6, '{"place":"The tower at night","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"A boat lay in the black water right under the tower wall while the map was read aloud. Why was it waiting under an empty tower?","forkA":"They posted a listener at the tower waiting for us to assemble the map and speak the way aloud.","forkB":"They were keeping watch on the shore road and hid under the wall when they heard our oars.","callback":"Yesterday you took their boat. Tonight someone took your words.","nudge":"{friend:Aim}, water rings spreading under the stones while our oars were already still, and a brief light out toward the island. Someone was down there before us.","nudgeIfLaid":null,"narratedSilence":"Garrick stands in the doorway looking out into the mist where the water laps at the wall.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"4-6-1","place":"the dark water under the wall","actions":[{"attr":"Aim","verb":"watch the water as you tie up"},{"attr":"Agility","verb":"lean out over the stones"}],"clueTitle":"The rings","clueText":"As you tie up at the tower, rings are already spreading from the dark under its wall, and your oars have been still for a minute.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-6-2","place":"the empty windows of the bell-chamber","actions":[{"attr":"Aim","verb":"look back the way you came"},{"attr":"Intellect","verb":"watch the water you crossed"}],"clueTitle":"One light","clueText":"Out toward the island, low on the water, a light shows for a breath and goes out. It does not show again.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-6-3","place":"the lights of Reedham","actions":[{"attr":"Aim","verb":"pick out every light on the shore"},{"attr":"Charm","verb":"watch the shore with the others, quietly"}],"clueTitle":"The lamp on the shingle","clueText":"Down on the shore, one lamp moves slowly along the shingle. It stops below her lane, and stays there.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We never asked what that would make them.\"* What has it made them?","weekQuestion":"Why has the Order left us alive?","pull":"**Down the stair, into the boat you took from them, and after that sound. Now.**"}'::jsonb)
on conflict (series_id, season_number, week, day) do update set data = excluded.data;

-- The Campfire for Week 5, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 5, 1, '{"place":"Reedham, and the waystone","narrated":false,"tone":"wry","cupNight":false,"opener":"North, then. That''s a long road for tired boots.","questionTitle":"The Seekers scattered four Stones to the far corners of the land, yet left the fifth at Highwall. Why keep it in the dead city?","forkA":"They kept the fifth at Highwall to stand guard over him where he fell.","forkB":"The fifth could not be carried away from Highwall without waking him.","callback":"Meira looked for a fifth and never found one. Today, on the road north, somebody had cut a line out of a stone.","nudge":"{friend:Intellect}, the miles left standing on the stone, and the second line under Highwall cut away to the last letter. Whose name sat under the city''s?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Was the waystone only a road marker, or part of the Seekers'' trail?","clickText":"The line under HIGHWALL was chiselled clean away like the king''s face on the coin, and the crack at the stone''s foot holds the same unnatural cold as every Seeker housing. The road marker was defaced, and the Seekers set their first sign in its foot."},"clicks":[{"a":"5-1-1","b":"5-1-2","text":"The line under HIGHWALL was chiselled clean away like the king''s face on the coin, and the crack at the stone''s foot holds the same unnatural cold as every Seeker housing. The road marker was defaced, and the Seekers set their first sign in its foot.","solves":true}],"riddle":null,"leads":[{"id":"5-1-1","place":"the worn face of the waystone","actions":[{"attr":"Craft","verb":"run a thumb along the cut-away line"},{"attr":"Intellect","verb":"hold the light low and look at its edges"}],"clueTitle":"The crisp edge","clueText":"Frost has eaten the old carving, but the edges of the cut-out line are crisp. Not one letter of it is left.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-1-2","place":"the crack at the waystone''s foot","actions":[{"attr":"Craft","verb":"scrape back the rime with a knife"},{"attr":"Aim","verb":"watch the crack while the beat comes"}],"clueTitle":"The rime stays","clueText":"Long after the fragment is out, the rime stays in the crack, in a mild wind. It is the same cold you have felt at every hiding place since the forest road.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-1-3","place":"the lane up from the shingle","actions":[{"attr":"Charm","verb":"walk up the lane and stop at a door"},{"attr":"Aim","verb":"look up the lane from the boat"}],"clueTitle":"Every window lit","clueText":"Every window up the lane has a lamp burning at midday, as Reedham does only on a dark-moon night.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"He gave us the war. Then it began to take.\"* What did it take from him?","weekQuestion":"What will it take for the fifth to end this?","pull":"You stay that night in Reedham. Up the lane, the lamp burns on in her window.\n\nAt dusk the heartbeat comes again, up through the floorboards and into the legs of your chair. It is louder than it was at dawn.\n\n**What is left in a city where nothing grows and nobody goes? The old kingdom''s road: two days north.**"}'::jsonb),
('dark-moon', 1, 5, 2, '{"place":"The old kingdom''s road","narrated":false,"tone":"wry","cupNight":false,"opener":"The grass on a war grave shouldn''t shiver. I''d say that''s the heartbeat.","questionTitle":"The heartbeat comes from Highwall for a few slow strokes at dusk and dawn, then stops. What is keeping him from waking outright?","forkA":"The four Stones have only thinned his sleep; it takes a certain night for him to wake.","forkB":"The fifth Stone is still in Highwall, holding the last of the Seekers'' lock shut.","callback":"On the Stillwater the birds went quiet at the first beat. Tonight the dogs came with it.","nudge":"{friend:Might}, one deep bite that held without tearing, and tracks that scattered the moment the beat died. What drove those dogs?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Were the dogs hunting for themselves?","clickText":"The dogs came in a straight line from the north while the ground beat, froze mid-stride the instant the beat stopped, and scattered every way after. The beat drove them while it lasted, and let them go when it stopped."},"clicks":[{"a":"5-2-1","b":"5-2-3","text":"The dogs came in a straight line from the north while the ground beat, froze mid-stride the instant the beat stopped, and scattered every way after. The beat drove them while it lasted, and let them go when it stopped.","solves":true}],"riddle":null,"leads":[{"id":"5-2-1","place":"the edge of the dark, past the cart","actions":[{"attr":"Aim","verb":"watch them at the edge of the dark"},{"attr":"Might","verb":"stand over the cart and hold your ground"}],"clueTitle":"Heads down","clueText":"When the beat stops, every dog stops with it, heads down, mid-stride. Not one runs away, and not one comes on.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-2-2","place":"the bandage on the man''s forearm","actions":[{"attr":"Charm","verb":"ask to see the arm"},{"attr":"Craft","verb":"tie the bandage again, properly"}],"clueTitle":"One bite","clueText":"Under the bandage is a single bite, deep and clean. The teeth went in once and held, and nothing tore.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-2-3","place":"where the dogs came out of the dusk","actions":[{"attr":"Aim","verb":"read the ground at first light"},{"attr":"Intellect","verb":"walk their tracks back the way they came"}],"clueTitle":"Scattered","clueText":"At first light their tracks come in together, in a straight line from the north. They go out scattered every way, the prints far apart.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"That is why it had to be us.\"* Had to be them, for what?","weekQuestion":"What will it take for the fifth to end this?","pull":"**The heartbeat is nearer every dusk, and it is coming from inside the city. Highwall, by noon.**"}'::jsonb),
('dark-moon', 1, 5, 3, '{"place":"The herald''s gate","narrated":false,"tone":"wry","cupNight":false,"opener":"High on the wall, and not a breath of green in the whole city. Sit down out of the wind.","questionTitle":"Highwall''s gate is barred from the inside with fresh timber in brackets worn bright by centuries of bars. Who is keeping it shut?","forkA":"The Order — keeping the dead city shut so no outsider disturbs their watch on the hall.","forkB":"Wardens left behind on the Seekers'' wall — barring the gate to keep what is inside from getting out.","callback":"Upriver, somebody kept a hidden path clear and a dog on new iron. Here somebody keeps a new bar on an old gate.","nudge":"{friend:Craft}, a broken stair knocked out with hammers long ago, and a fresh timber bar below. Somebody wants only one way in.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Was the gate barred long ago and left, or is someone tending it now?","clickText":"The timber bar was felled and squared within the last few days, and a single narrow path is trodden in the dust from the gatehouse straight up toward the smoke. Whoever tends the fire below the hall comes down to bar this gate."},"clicks":[{"a":"5-3-1","b":"5-3-2","text":"The timber bar was felled and squared within the last few days, and a single narrow path is trodden in the dust from the gatehouse straight up toward the smoke. Whoever tends the fire below the hall comes down to bar this gate.","solves":true}],"riddle":null,"leads":[{"id":"5-3-1","place":"the street behind the gate","actions":[{"attr":"Aim","verb":"look down into the street from the walkway"},{"attr":"Agility","verb":"lean out over the inner parapet"}],"clueTitle":"One trodden path","clueText":"In the dust of the street behind the gate, one narrow path is trodden from the bar up the hill, toward the smoke.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"5-3-2","place":"the near end of the new bar","actions":[{"attr":"Aim","verb":"pick out the bar''s end from above"},{"attr":"Craft","verb":"judge the timber by its colour"}],"clueTitle":"Still white","clueText":"The bar''s cut end is still white, and the axe-marks are sharp. It was put up within the last few days.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"5-3-3","place":"the broken stair","actions":[{"attr":"Agility","verb":"climb down to the gap in the stair"},{"attr":"Craft","verb":"look at the broken edges"}],"clueTitle":"Knocked out","clueText":"The missing steps lie at the stair''s foot in big, square pieces. Every break shows the bite of a hammer, weathered smooth.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"None of us gave to the fifth.\"* Why give to four and not to the fifth?","weekQuestion":"What will it take for the fifth to end this?","pull":"You spend the night up on the wall-walk, in the lee of the parapet, with the barred gate beneath you and that one thread of smoke going up into the dark.\n\n**Who bars a dead city from the inside, year after year? Down into the streets, following the wall.**"}'::jsonb),
('dark-moon', 1, 5, 4, '{"place":"The dead streets","narrated":false,"tone":"quiet","cupNight":true,"opener":null,"questionTitle":"Their boots have not stirred the dust in centuries, yet at dusk a helm seemed to turn and metal scraped on stone. Are the standing soldiers waking?","forkA":"No — they were frozen where they stood when he fell, and the dusk light played tricks on us.","forkB":"Yes — the heartbeat from the hall is beginning to stir them inside their armour.","callback":"On the road, when the beat stopped, the dogs stopped where they stood. These soldiers stopped mid-stride, and never started again.","nudge":"{friend:Aim}, unbroken dust round every boot, and one sound of iron on stone after we barred the door.","nudgeIfLaid":null,"narratedSilence":"Garrick wipes the dust from the cups with his sleeve, pours one more than there are of you, and sets the last at the empty place by the shuttered window facing up the hill. \"Family habit. We always pour one for whoever can''t be with us.\"","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"5-4-1","place":"the ground round the soldiers","actions":[{"attr":"Aim","verb":"look at the street round them"},{"attr":"Craft","verb":"crouch and look at the dust"}],"clueTitle":"Unbroken dust","clueText":"Round every boot the dust lies in one even skin. The only prints in it are yours.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"5-4-2","place":"the barred door of the empty house","actions":[{"attr":"Aim","verb":"keep an eye to the crack in the door"},{"attr":"Agility","verb":"sit by the door, ready, and listen"}],"clueTitle":"Metal on stone","clueText":"As the light goes, one sound comes from the direction of the street of soldiers: metal on stone, once. Then nothing.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"5-4-3","place":"the helms down the street","actions":[{"attr":"Aim","verb":"look along the line of helms"},{"attr":"Intellect","verb":"set each helm against the next"}],"clueTitle":"No two alike","clueText":"Every helm sits a little crooked on its neck, this way or that, no two the same. From the end of the street, any one of them could look turned.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We left them standing.\"* What stopped the soldiers mid-stride when he fell?","weekQuestion":"What will it take for the fifth to end this?","pull":"**Was that helm turned before? Nobody is sure. And the smoke is higher up the hill. The square below the hall.**"}'::jsonb),
('dark-moon', 1, 5, 5, '{"place":"Below the hall","narrated":false,"tone":"wry","cupNight":false,"opener":"One chalk stroke each dusk. Somebody''s counting.","questionTitle":"The Order has camped facing the sealed doors for generations, crossing off one stroke each dusk. What are they counting to?","forkA":"A fixed night on the calendar that they have known from the beginning.","forkB":"A sign from inside the hall as the heartbeat grows strong enough to break the seal.","callback":"At Reedham they kept Joss eight nights, waiting for something. Here they strike off one night every dusk.","nudge":"{friend:Intellect}, every stroke on that board drawn in the same square hand, and every head lifting when the beat comes. What ends when the count ends?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Is this camp a newly arrived war-band or a permanent post?","clickText":"The chalk strokes on the board have been gone over in the same hand until the wood is grooved, and extra bedrolls lie rolled and tied around the hearth for men on post. This camp is a permanent watch kept by a regular relief."},"clicks":[{"a":"5-5-1","b":"5-5-3","text":"The chalk strokes on the board have been gone over in the same hand until the wood is grooved, and extra bedrolls lie rolled and tied around the hearth for men on post. This camp is a permanent watch kept by a regular relief.","solves":true}],"riddle":null,"leads":[{"id":"5-5-1","place":"the board propped by the wall","actions":[{"attr":"Aim","verb":"read the board from the rubble"},{"attr":"Agility","verb":"creep close enough to see the chalk"}],"clueTitle":"One hand","clueText":"Every stroke on the board is in the same thick, square hand, the crossed ones and the ones still to cross. The chalk has been gone over many times, never redrawn.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-5-2","place":"the hooded figures at the fire","actions":[{"attr":"Aim","verb":"watch their faces from the rubble"},{"attr":"Agility","verb":"crawl close enough to see them"}],"clueTitle":"Every head lifts","clueText":"Every one of them sits facing the doors. When the beat comes, every head lifts at once, and stays lifted until it has passed.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-5-3","place":"the shell of the house across the square","actions":[{"attr":"Agility","verb":"slip round to its back wall"},{"attr":"Aim","verb":"look in through the broken window"}],"clueTitle":"More bedrolls","clueText":"Round the fire lie more bedrolls than there are people at it, each one rolled tight and tied.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Where we could watch it, and watch him.\"* Why did the Stone itself need watching?","weekQuestion":"What will it take for the fifth to end this?","pull":"You stay in the rubble until full dark, and keep your watches there by turns, with the Order''s fire showing red through the gaps all night.\n\n**Counting down to what? You hold five pieces, and the trail began on the wall. The wall again.**"}'::jsonb),
('dark-moon', 1, 5, 6, '{"place":"The wall again","narrated":false,"tone":"wry","cupNight":false,"opener":"A slit window, a hidden room, a night nobody heard you.","questionTitle":"The fifth Stone lies inside the wall beneath our feet, and we carry the mark in our blood. What happens when we open that room tonight?","forkA":"Our blood will wake the fifth right here in the wall and end his waking.","forkB":"Finding the fifth here is only half the task — it will have to be taken to his hall.","callback":"Every map before tonight was read out loud. Tonight it went hand to hand, and nobody heard.","nudge":"{friend:Aim}, two shallow dips worn into the parapet where elbows rested, facing straight up at the hall.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How did the room stay hidden from the Order for centuries?","clickText":"The walkway here was built a full stride wider on the city side, and the slit window is set so low in the stone face that it cannot be seen from the square. Anyone not standing on this parapet would take the wall for solid rock."},"clicks":[{"a":"5-6-1","b":"5-6-3","text":"The walkway here was built a full stride wider on the city side, and the slit window is set so low in the stone face that it cannot be seen from the square. Anyone not standing on this parapet would take the wall for solid rock.","solves":true}],"riddle":null,"leads":[{"id":"5-6-1","place":"the city side of the wall, below the walk","actions":[{"attr":"Aim","verb":"lean out over the parapet"},{"attr":"Might","verb":"brace on the parapet and lean far out"}],"clueTitle":"The narrow slit","clueText":"The slit is no wider than a hand, low in the wall''s face. Unless you lean out over the parapet and look straight down the stone, you cannot see it at all.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-6-2","place":"the parapet on the city side","actions":[{"attr":"Craft","verb":"run a hand along the parapet''s top"},{"attr":"Might","verb":"lean your weight where others leaned"}],"clueTitle":"Two shallow dips","clueText":"Above where the map points, the parapet''s top is worn into two shallow dips, the width of a pair of elbows. They face the hall.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-6-3","place":"the forty paces of open stone","actions":[{"attr":"Agility","verb":"pace the walk while their heads are turned"},{"attr":"Intellect","verb":"measure the walk against the gate-tower"}],"clueTitle":"A stride wider","clueText":"Here the walk is wider than at the gate, by a good stride. All of the extra width is on the city side.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"The five were joined.\"* Joined to do what?","weekQuestion":"What will it take for the fifth to end this?","pull":"**The watch has changed. It is dark enough. Into the wall, tonight.**"}'::jsonb)
on conflict (series_id, season_number, week, day) do update set data = excluded.data;

-- The Campfire for Week 6, generated by scripts/gen-campfire-sql.ts. Do not edit by hand.
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 6, 1, '{"place":"The wall room (Six nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"Quiet''s good in a hole in a wall. I''ll take it.","questionTitle":"The searchers walked past our door twice and found nothing, yet the watchman at the board still looked down at the wall at dusk. Why?","forkA":"He still believes someone is hiding in the wall; the Order has not given up the search.","forkB":"He is only checking that the rampart stays dark before he strikes the night''s chalk.","callback":"At dusk you crossed the wall and nobody heard. By the end of the night a watchman was looking straight at your window.","nudge":"{friend:Aim}, he paused with the chalk in his hand and looked down the hill at the wall before he struck the board. Was he hunting a light, or keeping a routine?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Could a candle inside the niche ever show through the slit?","clickText":"The stone niche faces the inner wall away from the slit, and its only candle-soot is centuries old. Even when the Seekers kept a light behind the Stone, no flame could ever show in the square."},"clicks":[{"a":"6-1-1","b":"6-1-3","text":"The stone niche faces the inner wall away from the slit, and its only candle-soot is centuries old. Even when the Seekers kept a light behind the Stone, no flame could ever show in the square.","solves":true}],"riddle":null,"leads":[{"id":"6-1-1","place":"the slit, after dark","actions":[{"attr":"Aim","verb":"watch the lanterns from the slit"},{"attr":"Intellect","verb":"follow where each lantern goes"}],"clueTitle":"No light inside","clueText":"Not a candle burns in the room. Every lantern you can see from the slit is out in the square, and none of them reaches in.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-1-2","place":"the board in the square","actions":[{"attr":"Aim","verb":"watch the board from the slit at dusk"},{"attr":"Intellect","verb":"watch the man with the chalk, not the board"}],"clueTitle":"One look down the hill","clueText":"At dusk the watchman with the chalk stops before he strikes the board. He turns, looks down the hill at the wall, and then strikes it.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-1-3","place":"the stone niche where it lay","actions":[{"attr":"Craft","verb":"hold a hand inside and feel the stone"},{"attr":"Intellect","verb":"look at the niche with the lamp unlit"}],"clueTitle":"The old soot","clueText":"The back of the stone niche is blackened in one small round patch, the way a candle marks stone over years. The niche faces the inner wall, away from the slit.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"We let them go.\"* Why spare anyone, on a night like that?","weekQuestion":"What will the fifth do in his hall?","pull":"**The hall is sealed, and the Seekers left a way in, somewhere. The arrow points down: the defenders'' barracks, under the wall.**"}'::jsonb),
('dark-moon', 1, 6, 2, '{"place":"The barracks under the wall (Five nights)","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"When the ceiling came down, a hollowed soldier stood in our doorway, looked at the fallen stone, and walked on toward the hall at the heartbeat. What is moving the dead garrison across Highwall?","forkA":"The waking heart inside the hall is drawing every soldier back to the place where he fell.","forkB":"They are still carrying out their last order from the night the barracks emptied: form ranks at the hall.","callback":"Last week you couldn''t be sure a helm had turned toward you. Today one stood in your doorway and looked at the fallen stone instead.","nudge":"{friend:Agility}, empty spear-racks swept clean, bowls never filled, and every iron boot in the city stepping once when the beat comes.","nudgeIfLaid":null,"narratedSilence":"Garrick rests his head against the cold masonry, listening to the hollow thud of the earth below in silence.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"6-2-1","place":"where the spears once stood","actions":[{"attr":"Craft","verb":"look at the dust under the racks"},{"attr":"Intellect","verb":"walk the racks end to end"}],"clueTitle":"The swept racks","clueText":"The spear-racks along the wall are empty, and the dust under every one is swept clean in the same short arc.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-2-2","place":"the stair up to the street","actions":[{"attr":"Agility","verb":"climb to the top step and listen"},{"attr":"Intellect","verb":"count what you hear"}],"clueTitle":"Every foot at once","clueText":"When the heartbeat comes, you hear iron move all over the city at once: one scrape of a foot from every street, then quiet.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-2-3","place":"the kitchen whose fire went out","actions":[{"attr":"Craft","verb":"look over the board and the pot"},{"attr":"Might","verb":"lift the lid of the cold pot"}],"clueTitle":"Bowls never filled","clueText":"In the kitchen, bowls are set out along the board for a meal, and a ladle lies in the cold pot. Not one bowl was filled.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"That is how we found the shards.\"* How could a mark help anyone find one?","weekQuestion":"What will the fifth do in his hall?","pull":"**They are not coming for you. They are going to him. And wherever the Seekers'' way in begins, it begins at his walls. The great square, after dark.**"}'::jsonb),
('dark-moon', 1, 6, 3, '{"place":"The great square (Four nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"The hall''s warm from within. More faithful arriving. What''s missing is a door.","questionTitle":"The hall''s stone wall is warm from the floor up behind sealed bronze doors, while new arrivals stack clean robes by their fire outside. Has the Order already set the four Stones inside, or are they still waiting outside for the last night?","forkA":"The four Stones are already set around him on the floor inside, warming the stone.","forkB":"The Stones are still outside with the faithful, waiting to be carried in on the dark moon.","callback":"The soldiers are three streets nearer the hall. Round the Order''s fire there are twice as many as before.","nudge":"{friend:Intellect}, clean robes folded on top of their road-packs outside, and warmth in the stone wall only from knee-height down.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Where is the heat in the hall''s wall coming from?","clickText":"An unbroken bank of dust lies across the seam of the bronze doors, and the stone wall is warm only from knee-height down. The front doors have never opened, and whatever is warming the hall lies flat on the floor inside."},"clicks":[{"a":"6-3-1","b":"6-3-3","text":"An unbroken bank of dust lies across the seam of the bronze doors, and the stone wall is warm only from knee-height down. The front doors have never opened, and whatever is warming the hall lies flat on the floor inside.","solves":true}],"riddle":null,"leads":[{"id":"6-3-1","place":"the foot of the great doors","actions":[{"attr":"Agility","verb":"slip along the wall to the doors"},{"attr":"Craft","verb":"look at the ground under the seam"}],"clueTitle":"The unbroken drift","clueText":"At the foot of the great doors, dust has drifted against the seam in one smooth bank, from post to post. Nothing has crossed it.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"6-3-2","place":"the ruined house across from the hall","actions":[{"attr":"Aim","verb":"pick out what is stacked by their fire"},{"attr":"Agility","verb":"creep along the ruined house''s wall"}],"clueTitle":"Clean robes","clueText":"By the Order''s fire the new men''s packs are stacked in a row. On top of each lies a folded robe, brushed clean of the road.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"6-3-3","place":"the hall''s great wall","actions":[{"attr":"Craft","verb":"feel the stone, hand over hand"},{"attr":"Might","verb":"climb a little way and feel higher"}],"clueTitle":"Warm low down","clueText":"Move your palm up the wall and the stone cools. The warmth is only low down, at the height of your knee and below.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"None of us could bear to lift him.\"* What kept them from lifting him?","weekQuestion":"What will the fifth do in his hall?","pull":"You cross back on the change of the watch, while the two men are looking at each other, and sleep in the wall room with the warmth of that stone still in your palm.\n\n**He is on the other side of this wall. Inside, on the night the moon goes dark, with the fifth: that is the whole plan now. The cracked hill behind the hall.**"}'::jsonb),
('dark-moon', 1, 6, 4, '{"place":"The hill behind the hall (Three nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"That hill was steeper than it looked. Sit.","questionTitle":"Every other soldier in Highwall faces the hall. Why has this one stood in the mouth of the Seekers'' crack since the war ended, facing out?","forkA":"The Seekers left it to bar their own secret passage after they sealed the hall and walked out.","forkB":"It was keeping the king''s last watch — guarding the back of his throne against anyone coming down the hill.","callback":"Upriver, a dog on a chain kept the hidden path. Today a soldier stood in the crack with its back to the hall.","nudge":"{friend:Craft}, two hollows worn into solid stone by iron boots, and the heartbeat louder right behind the blank rock than anywhere else.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How long had the sentinel stood in the mouth of the crack?","clickText":"The grit behind the soldier lay smooth and untouched until your boots marked it, while the rock under its iron soles is worn into two shallow hollows. Nobody has passed down this crack since the war ended, and that soldier never left its post."},"clicks":[{"a":"6-4-1","b":"6-4-2","text":"The grit behind the soldier lay smooth and untouched until your boots marked it, while the rock under its iron soles is worn into two shallow hollows. Nobody has passed down this crack since the war ended, and that soldier never left its post.","solves":true}],"riddle":null,"leads":[{"id":"6-4-1","place":"inside the crack, by lamplight","actions":[{"attr":"Agility","verb":"go in sideways, lamp first"},{"attr":"Aim","verb":"light the ground ahead and look"}],"clueTitle":"The untouched grit","clueText":"Past where the soldier stood, the grit on the crack''s floor lies smooth and untouched. Your boots are the first marks in it.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"6-4-2","place":"the 